window.TRADUCTIONS = {"nav.accueil": {"en": "Home","pt": "Início","zh": "首页"},"nav.virtuel": {"en": "Virtual Lab","pt": "Laboratório virtual","zh": "虚拟实验室"},"nav.neuroexo": {"en": "NeuroExoAI","pt": "NeuroExoAI","zh": "NeuroExoAI"},"nav.devkit": {"en": "RealiDevKit","pt": "RealiDevKit","zh": "RealiDevKit"},"nav.realia": {"en": "RealiaStation","pt": "RealiaStation","zh": "RealiaStation"},"nav.luna": {"en": "LunaGalaxie","pt": "LunaGalaxie","zh": "LunaGalaxie"},"nav.social": {"en": "Social project","pt": "Projeto social","zh": "社会项目"},"nav.blueprint": {"en": "Blueprint","pt": "Blueprint","zh": "蓝图"},"nav.archi": {"en": "The Architect","pt": "O Arquiteto","zh": "建筑师"},"nav.cabinet": {"en": "Cabinet & Services","pt": "Gabinete & Serviços","zh": "工作室与服务"},"nav.wishlist": {"en": "Wishlist","pt": "Lista de desejos","zh": "心愿单"},"nav.boutique": {"en": "Shop","pt": "Loja","zh": "商店"},"commun.soutenir": {"en": "Support","pt": "Apoiar","zh": "支持"},"commun.retour": {"en": "← Home","pt": "← Início","zh": "← 首页"},"commun.suivant": {"en": "Next drawer","pt": "Próxima gaveta","zh": "下一个抽屉"},"commun.dernier": {"en": "Last drawer","pt": "Última gaveta","zh": "最后一个抽屉"},"commun.nonmed": {"en": "open-source project · research prototype, not a medical device","pt": "projeto aberto · protótipo de pesquisa, não é dispositivo médico","zh": "开源项目 · 研究原型，非医疗器械"},"commun.pied_liens": {"en": "Equipment","pt": "Equipamentos","zh": "设备"},"commun.bientot": {"en": "Coming soon","pt": "Em breve","zh": "即将推出"},"audio.titre": {"en": "Luna · soundtrack","pt": "Luna · trilha sonora","zh": "Luna · 原声"},"audio.jouer": {"en": "Play Luna","pt": "Ouvir Luna","zh": "播放 Luna"},"audio.pause": {"en": "Pause","pt": "Pausar","zh": "暂停"},"index.slogan1": {"en": "We sense, we stimulate, we simulate.","pt": "Captamos, estimulamos, simulamos.","zh": "我们采集，我们刺激，我们仿真。"},"index.slogan2": {"en": "The path is there; walking it is what will widen it.","pt": "O caminho está lá; é percorrê-lo que vai alargá-lo.","zh": "路就在那里，走上去，它才会变宽。"},"index.badge": {"en": "🚧 WORK IN PROGRESS — EVOLVING WEBSITE","pt": "🚧 EM OBRAS — SITE EM EVOLUÇÃO","zh": "🚧 建设中 — 第一阶段 Beta 发布"},"index.bienvenue": {"en": "Welcome to the adventure!","pt": "Bem-vindo à aventura!","zh": "欢迎来到这场冒险！"},"index.titre_1": {"en": "From the spark to the impulse","pt": "Da faísca ao impulso","zh": "从火花到冲动"},"index.titre_2": {"en": "an exoskeleton for the future","pt": "um exoesqueleto para o futuro","zh": "一台面向未来的外骨骼"},"index.cta_music": {"en": "Play music","pt": "Play music","zh": "Play music"},"index.banniere": {"en": "From the spark to the impulse, an exoskeleton for the future","pt": "Da faísca ao impulso, um exoesqueleto para o futuro","zh": "从火花到冲动，一台面向未来的外骨骼"},"index.sous": {"en": "Open-source neuro-robotics, agentic AI and international solidarity. A research prototype, published as it goes.","pt": "Neuro-robótica aberta, IA agêntica e solidariedade internacional. Um protótipo de pesquisa, publicado à medida que avança.","zh": "开源神经机器人、智能体人工智能与国际团结。一个逐步公开的研究原型。"},"index.cta1": {"en": "Start the experience & listen to Luna","pt": "Ativar a experiência e ouvir Luna","zh": "开启体验并聆听 Luna"},"index.cta2": {"en": "Read the manifesto","pt": "Ler o manifesto","zh": "阅读宣言"},"index.titre": {"en": "From the spark to the impulse","pt": "Da faísca ao impulso","zh": "从火花到冲动"},"index.lead": {"en": "An incomplete C6-C7 injury does not erase everything: the command to move still leaves, and the impulse can be felt. This project was born from an image seen on television, and it has been moving forward ever since, one component at a time.","pt": "Uma lesão C6-C7 incompleta não apaga tudo: a ordem de movimento ainda parte, e o impulso é sentido. Este projeto nasceu de uma imagem vista na televisão e avança desde então, um componente por vez.","zh": "不完全的 C6-C7 损伤并没有抹去一切：运动的指令依然发出，冲动依然能被感知。这个项目诞生于电视上看到的一个画面，并从此一步步向前。"},"index.reboot_titre": {"en": "2006 — the reboot","pt": "2006 — o reboot","zh": "2006 — 重启"},"index.reboot_txt": {"en": "An accident. One life stops, another begins. Eight years later, an image seen on television will give it a direction.","pt": "Um acidente. Uma vida termina, outra começa. Oito anos depois, uma imagem vista na televisão vai dar-lhe uma direção.","zh": "一场事故。一种生活结束，另一种开始。八年后，电视上的一个画面为它指明了方向。"},"index.histoire_titre": {"en": "The trigger: 12 June 2014","pt": "O estalo: 12 de junho de 2014","zh": "那一刻：2014 年 6 月 12 日"},"index.histoire_1": {"en": "World Cup, São Paulo. A paraplegic patient rises from his wheelchair and kicks off the tournament, supported by Dr Miguel Nicolelis's exoskeleton. Millions see it; one person decides this will be his life.","pt": "Copa do mundo, São Paulo. Um paciente paraplégico se levanta da cadeira e dá o pontapé inicial, sustentado pelo exoesqueleto do Dr. Miguel Nicolelis. Milhões veem a cena; uma pessoa decide que será a sua vida.","zh": "世界杯，圣保罗。一位截瘫患者从轮椅上站起，在 Miguel Nicolelis 博士的外骨骼支撑下开球。数百万人看到了这一幕；其中一个人决定，这就是他的一生。"},"index.histoire_2": {"en": "The idea matures for years, with no lab and no budget — just a conviction and a notebook. Then AI arrives, the compute machine gets built, and act 3 joins phase 1: a measurable, open, published test bench.","pt": "A ideia amadurece por anos, sem laboratório nem orçamento — só uma convicção e um caderno. Depois chega a IA, a máquina de cálculo é montada, e o ato 3 junta-se à fase 1: uma bancada de testes mensurável, aberta, publicada.","zh": "这个想法酝酿多年，没有实验室，也没有预算——只有一份信念和一本笔记。然后人工智能到来，计算主机搭起，第一阶段成为可能：一个可测量、开放、公开的试验台。"},"index.orient_titre": {"en": "The path, step by step","pt": "O caminho, passo a passo","zh": "这条路，一步一步"},"index.orient_lead": {"en": "Each drawer of the site is a step of the project. Read them in order, or jump to the one you care about.","pt": "Cada gaveta do site é uma etapa do projeto. Leia em ordem, ou vá direto à que interessa.","zh": "网站的每个抽屉都是项目的一个阶段。你可以按顺序读，也可以直接跳到感兴趣的那一个。"},"virtuel.badge": {"en": "🚧 WORK IN PROGRESS — LAUNCHES WHEN FUNDED","pt": "🚧 EM OBRAS — LANÇA COM O FINANCIAMENTO","zh": "🚧 建设中 — 资金到位即启动"},"virtuel.titre": {"en": "The body before the metal","pt": "O corpo antes do metal","zh": "先有身体，后有金属"},"virtuel.lead": {"en": "Before carrying a human, the machine learns to walk. Before touching metal, everything is tuned in a virtual world: the body first, the numbers next, the material last. A mistake in simulation costs a line of code; the same mistake in the workshop costs a machined part and three weeks.","pt": "Antes de carregar um humano, a máquina aprende a andar. Antes de tocar no metal, tudo se ajusta num mundo virtual: o corpo primeiro, os números depois, a matéria por último. Um erro na simulação custa uma linha de código; o mesmo erro na oficina custa uma peça usinada e três semanas.","zh": "在承载人之前，机器先要学会走路。在碰金属之前，一切都在虚拟世界里调好：先是身体，再是数字，最后才是材料。仿真里犯一次错，只花一行代码；工坊里同样的错，要花一个加工件和三周时间。"},"virtuel.c1t": {"en": "For me, the pilot","pt": "Para mim, o piloto","zh": "对我这个试飞者"},"virtuel.c1d": {"en": "Training in virtual reality to send the order to move, and to retrain the impulses that run through my legs — before doing it on the real machine. The simulator is my first rehabilitation table: I can repeat, fail, start again, with no risk and nobody to wait for.","pt": "Treinar no virtual para enviar a ordem de mover e reeducar os impulsos que percorrem as minhas pernas — antes de o fazer na máquina real. O simulador é a minha primeira mesa de reabilitação: posso repetir, errar, recomeçar, sem risco e sem esperar por ninguém.","zh": "在虚拟里练习发出「动」的指令，重新训练经过双腿的那些冲动——然后再上真机。仿真器是我的第一张康复台：可以重复、可以失败、可以重来，没有风险，也不用等任何人。"},"virtuel.c2t": {"en": "For the AI, the Exo-Robot","pt": "Para a IA, o Exo-Robô","zh": "对 AI 来说，外骨骼机器人"},"virtuel.c2d": {"en": "It is not a simple mechanical exoskeleton. It is an intelligent hybrid exo-robot, and it too must learn to walk in a virtual world before carrying a human: learn the right reactions, correct the wrong ones, absorb a thousand falls that happen to no one.","pt": "Não é um simples exoesqueleto mecânico. É um exorrobô híbrido inteligente, e ele também precisa aprender a andar num mundo virtual antes de carregar um humano: aprender as reações certas, corrigir as erradas, absorver mil quedas que não acontecem a ninguém.","zh": "它不是一台单纯的机械外骨骼，而是一个智能的混合外骨骼机器人。它同样要先在虚拟世界里学会走路，才敢承载一个人：学会正确的反应，纠正错误的反应，承受一千次不会摔到任何人身上的跌倒。"},"virtuel.c3t": {"en": "What stays open","pt": "O que fica aberto","zh": "保持开放的部分"},"virtuel.c3d": {"en": "Models, session settings, latency curves: everything is published. If it works for me, it must be reproducible elsewhere — including when it fails. A closed test bench is worth nothing for what comes next.","pt": "Modelos, ajustes de sessão, curvas de latência: tudo é publicado. Se funciona comigo, tem de ser reproduzível noutro lugar — inclusive quando falha. Um banco de ensaio fechado não vale nada para o que vem depois.","zh": "模型、训练设置、延迟曲线：全部公开。若在我身上有效，就必须能在别处复现——包括失败的部分。封闭的试验台对下一步毫无价值。"},"virtuel.img1_leg": {"en": "Exoskeleton sketch — to be replaced by the generated visual","pt": "Croqui do exoesqueleto — a substituir pelo visual gerado","zh": "外骨骼草图——将替换为生成的图像"},"virtuel.img2_leg": {"en": "Safety ramp and gantry — to be replaced by the generated visual","pt": "Rampa e pórtico de segurança — a substituir pelo visual gerado","zh": "安全坡道与龙门架——将替换为生成的图像"},"neuroexo.badge": {"en": "🚧 WORK IN PROGRESS — BETA ARCHITECTURE","pt": "🚧 EM OBRAS — ARQUITETURA BETA","zh": "🚧 建设中 — 架构 Beta"},"neuroexo.titre": {"en": "NeuroExoAI — the real-time harness","pt": "NeuroExoAI — o arnês de tempo real","zh": "NeuroExoAI——实时背具"},"neuroexo.lead": {"en": "The harness listens to the brain and the muscles, the AI decides, the machine assists. At every instant a loop closes — and that loop is what retrains walking, step by step, session after session.","pt": "O arnês escuta o cérebro e os músculos, a inteligência artificial decide, a máquina assiste. A cada instante um laço se fecha — e é esse laço que reeduca a marcha, passo a passo, sessão após sessão.","zh": "背具倾听大脑与肌肉，人工智能做决定，机器去辅助。每一刻都有一个回路闭合——真正重新训练行走的，就是这个回路，一步步，一次次训练。"},"neuroexo.c1t": {"en": "The harness listens","pt": "O arnês escuta","zh": "背具在倾听"},"neuroexo.c1d": {"en": "Sensors on the head read the intention to move, and sensors on the legs read the micro-signals the muscle still sends, even when the movement no longer gets through. Nothing is guessed: everything is measured.","pt": "Sensores na cabeça leem a intenção de movimento, e sensores nas pernas leem os micro-sinais que o músculo ainda envia, mesmo quando o movimento já não passa. Nada é adivinhado: tudo é medido.","zh": "头部的传感器读取「想动」的意图，腿上的传感器读取肌肉即使动作不再通过时仍在发出的微弱信号。不靠猜，全部靠测。"},"neuroexo.c2t": {"en": "The AI assists at the right moment","pt": "A IA assiste no momento certo","zh": "AI 在对的时刻出手"},"neuroexo.c2d": {"en": "The AI cross-reads both signals in real time: it understands what you intend to do and what the muscle can still give. It then assists the movement and stimulates the muscles at the right moment — not too early, not too hard.","pt": "A IA cruza as duas informações em tempo real: entende o que você quer fazer e o que o músculo ainda pode dar. Então assiste o movimento e estimula eletricamente os músculos no momento certo — nem cedo demais, nem forte demais.","zh": "AI 实时交叉这两种信息：明白你想做什么，也知道肌肉还能给出多少。于是它辅助动作，并在对的那一刻电刺激肌肉——不早一步，也不过猛。"},"neuroexo.c3t": {"en": "The Brain → Muscle → Exo-Robot → Brain loop","pt": "O laço Cérebro → Músculo → Exorrobô → Cérebro","zh": "大脑 → 肌肉 → 外骨骼机器人 → 大脑 的回路"},"neuroexo.c3d": {"en": "Brain: the intention. Muscle: the response. Exo-Robot: the assistance. And back to the brain, which learns. Every successful step strengthens the next one: that is how walking is retrained, step by step, session after session. And if the program stops, the machine freezes — safety does not depend on software.","pt": "Cérebro: a intenção. Músculo: a resposta. Exorrobô: a assistência. E de volta ao cérebro, que aprende. Cada passo bem-sucedido fortalece o seguinte: é assim que se reeduca a marcha, passo a passo, sessão após sessão. E se o programa parar, a máquina congela — a segurança não depende do software.","zh": "大脑：意图。肌肉：回应。外骨骼机器人：辅助。再回到大脑，它因此学习。每一步成功都会强化下一步：行走就是这样重新训练出来的，一步步，一次次训练。而程序一旦停止，机器就定住——安全不依赖软件。"},"neuroexo.journal_titre": {"en": "Build-in-public log","pt": "Diário build-in-public","zh": "公开构建日志"},"neuroexo.j1": {"en": "2026-11-16 — System 1 architecture settled: two clocks, one boundary, no model in the control loop.","pt": "2026-11-16 — Arquitetura do Sistema 1 fechada: dois relógios, uma fronteira, nenhum modelo no laço de comando.","zh": "2026-11-16 — 系统 1 架构确定：两个时钟、一条边界，控制回路中没有任何模型。"},"neuroexo.j2": {"en": "2026-11-10 — Safety rules isolated from transport: they can be tested without a gantry or power supply.","pt": "2026-11-10 — Regras de segurança isoladas do transporte: testáveis sem pórtico nem fonte.","zh": "2026-11-10 — 安全规则与传输层解耦：无需龙门架或电源即可测试。"},"neuroexo.j3": {"en": "2026-11-02 — Decision: digital twin before machining, so no mistake is paid for in metal.","pt": "2026-11-02 — Decisão: gêmeo digital antes da usinagem, para não pagar cada erro em metal.","zh": "2026-11-02 — 决定：先数字孪生再加工，避免每个错误都用金属偿还。"},"devkit.badge": {"en": "⚡ IN PRODUCTION — PUBLIC RELEASE IN PREPARATION","pt": "⚡ EM PRODUÇÃO — ABERTURA PÚBLICA EM PREPARAÇÃO","zh": "⚡ 生产运行中 — 公开发布筹备中"},"devkit.titre": {"en": "RealiDevKit — the workshop that stays at home","pt": "RealiDevKit — a oficina que fica na sua máquina","zh": "RealiDevKit——留在你自己机器上的工坊"},"devkit.lead": {"en": "The RealiaDevKit team opens a workshop that runs entirely on your machine: your models, your files, your VRAM, and nobody else. Data never leaves the station. A swarm of specialised agents orchestrates your projects from idea to commit — the autonomy of a CTO, the confidentiality of a vault.","pt": "A equipe RealiaDevKit abre uma oficina que roda inteiramente na sua máquina: seus modelos, seus arquivos, sua VRAM, e mais ninguém. Os dados nunca saem da estação. Um enxame de agentes especializados orquestra seus projetos da ideia ao commit — a autonomia de um CTO, a confidencialidade de um cofre.","zh": "RealiaDevKit 团队为你打开一间完全运行在你自己机器上的工坊：你的模型、你的文件、你的显存，没有别人。数据永不离开工作站。一群专职智能体把你的项目从想法编排到提交——CTO 的自主，金库的保密。"},"devkit.c1t": {"en": "What actually runs today","pt": "O que roda hoje","zh": "今天真正在跑的"},"devkit.c1d": {"en": "A planner and a coder take turns on a single 16 GB card: the first splits the request into work orders, the second writes the code and proves it. Around them, 66 tools, 16 role sheets, a queue that empties overnight and a log that keeps everything. One machine is enough — the one already under the desk.","pt": "Um planejador e um programador se revezam numa única placa de 16 GB: o primeiro divide o pedido em ordens de serviço, o segundo escreve o código e o prova. Ao redor, 66 ferramentas, 16 fichas de papel, uma fila que se esvazia à noite e um registro que guarda tudo. Uma só máquina basta — a que já está debaixo da mesa.","zh": "一个规划器与一个编码器在同一块 16 GB 显卡上轮流工作：前者把请求拆成工单，后者写代码并证明它。周围是 66 个工具、16 份角色说明、一条夜里清空的队列，以及记录一切的日志。一台机器就够——就是桌下那台。"},"devkit.c2t": {"en": "What never leaves the station","pt": "O que não sai da estação","zh": "不离开工作站的东西"},"devkit.c2d": {"en": "Models, files, images, conversations, code: everything stays on the disk. No outbound call is needed to work, no account to create, no per-request bill. Confidentiality is not a contractual promise, it is a consequence of the wiring.","pt": "Modelos, arquivos, imagens, conversas, código: tudo fica no disco. Nenhuma chamada externa é necessária para trabalhar, nenhuma conta a criar, nenhuma fatura por requisição. A confidencialidade não é promessa de contrato, é consequência da ligação.","zh": "模型、文件、图像、对话、代码：全部留在磁盘上。工作无需任何外呼，无需注册账号，没有按次计费。保密不是合同承诺，而是接线方式的必然结果。"},"devkit.c3t": {"en": "What was removed before opening","pt": "O que foi removido antes de abrir","zh": "开放之前拿掉的东西"},"devkit.c3d": {"en": "Keys, personal paths, working data and history: everything was purged, commit by commit, not just in the latest state. The check also runs on the files served to the browser — a secret left in a public page cannot be undone.","pt": "Chaves, caminhos pessoais, dados de trabalho e histórico: tudo foi purgado, commit por commit, não só no último estado. A checagem também roda nos arquivos servidos ao navegador — um segredo esquecido numa página pública não se recupera.","zh": "密钥、个人路径、工作数据与历史：逐次提交全部清除，而不只是最新状态。检查同样作用于发给浏览器的文件——留在公开页面上的密钥无法挽回。"},"devkit.journal_titre": {"en": "Build-in-public log","pt": "Diário build-in-public","zh": "公开构建日志"},"devkit.j1": {"en": "2026-11-17 — Tooled audit of the site: accessibility 100 on all twelve pages, zero HTML conformance error.","pt": "2026-11-17 — Auditoria instrumentada do site: acessibilidade 100 nas doze páginas, zero erro de conformidade HTML.","zh": "2026-11-17 — 网站工具化审计：十二个页面无障碍 100，HTML 合规零错误。"},"devkit.j2": {"en": "2026-11-09 — Separate public repository, 650 tracked files, leak checks green.","pt": "2026-11-09 — Repositório público separado, 650 arquivos rastreados, checagens de vazamento verdes.","zh": "2026-11-09 — 独立公开仓库，650 个受控文件，泄漏检查通过。"},"realia.badge": {"en": "🚧 WORK IN PROGRESS — SETUP IN PREPARATION","pt": "🚧 EM OBRAS — SETUP EM PREPARAÇÃO","zh": "🚧 建设中 — 环境搭建中"},"realia.titre": {"en": "RealiaStation — the study","pt": "RealiaStation — o gabinete","zh": "RealiaStation——工作室"},"realia.lead": {"en": "The future production station, built with the DevKit: the latest Hermes release and the SuperAgent harness to orchestrate an army of sub-agents. This is where the content will come from.","pt": "A futura estação de produção, construída com o DevKit: a última versão do Hermes e o arnês SuperAgent para orquestrar um exército de subagentes. É daqui que sairá o conteúdo.","zh": "未来的生产站，用 DevKit 搭建：最新版 Hermes 与 SuperAgent 背具，指挥一支子智能体军队。内容将从这里产出。"},"realia.c1t": {"en": "Hermes + SuperAgent","pt": "Hermes + SuperAgent","zh": "Hermes + SuperAgent"},"realia.c1d": {"en": "One agent framing the work, a swarm of sub-agents executing: research, writing, editing, publishing.","pt": "Um agente que enquadra, uma nuvem de subagentes que executa: pesquisa, escrita, edição, publicação.","zh": "一个负责定框的智能体，一群负责执行的子智能体：调研、写作、剪辑、发布。"},"realia.c2t": {"en": "LunaGalaxie's factory","pt": "A fábrica da LunaGalaxie","zh": "LunaGalaxie 的工厂"},"realia.c2d": {"en": "The station will produce the episodes, animate the crew of virtual influencers and run their channels. The audience then funds the social projects.","pt": "A estação produzirá os episódios, animará a tripulação de influenciadoras virtuais e cuidará das redes. A audiência financia então os projetos sociais.","zh": "该站将制作剧集、驱动虚拟网红团队并运营其社交平台。由此获得的受众，反过来资助社会项目。"},"realia.c3t": {"en": "Why a station, not a cloud","pt": "Por que uma estação, e não uma nuvem","zh": "为什么是工作站，而不是云"},"realia.c3d": {"en": "Controlled cost, data at home, no dependency on usage pricing. The GPU runs at night, like an oven.","pt": "Custo controlado, dados em casa, sem depender de preço por uso. A GPU roda à noite, como um forno.","zh": "成本可控、数据在家、不依赖按量计费。GPU 像烤炉一样夜里运转。"},"realia.lien_titre": {"en": "And LunaGalaxie?","pt": "E a LunaGalaxie?","zh": "那 LunaGalaxie 呢？"},"realia.lien_txt": {"en": "RealiaStation is the hand that produces; LunaGalaxie is the voice that tells. One makes the images and episodes, the other carries them to the audience.","pt": "A RealiaStation é a mão que produz; a LunaGalaxie é a voz que conta. Uma faz as imagens e os episódios, a outra os leva ao público.","zh": "RealiaStation 是生产的手，LunaGalaxie 是讲述的声音。一个制作画面与剧集，另一个把它们带到观众面前。"},"realia.lien_cta": {"en": "Board the GhostSheller →","pt": "Entrar no GhostSheller →","zh": "登上 GhostSheller →"},"luna.badge": {"en": "Incoming transmission","pt": "Transmissão recebida","zh": "收到传输"},"luna.titre": {"en": "LunaGalaxie","pt": "LunaGalaxie","zh": "LunaGalaxie"},"luna.lead": {"en": "Spokesperson and narrator of the project. She travels aboard the GhostSheller, a thousand-year-old quantum ship with black-hole propulsion, surrounded by her loyal crew.","pt": "Porta-voz e narradora do projeto. Viaja a bordo do GhostSheller, nave quântica milenar com propulsão de buraco negro, cercada por sua fiel tripulação.","zh": "项目的代言人与讲述者。她乘坐千年量子飞船 GhostSheller，以黑洞为推进，身边是忠诚的船员。"},"luna.prod_titre": {"en": "Produced by RealiaStation","pt": "Produzida pela RealiaStation","zh": "由 RealiaStation 制作"},"luna.prod_txt": {"en": "Episodes, images and voices are made by the production station. The audience it generates funds the Integrated Isles.","pt": "Episódios, imagens e vozes são feitos pela estação de produção. A audiência que ela gera financia as Ilhas Integradas.","zh": "剧集、画面与声音均由生产站制作。它带来的受众，资助综合之岛。"},"luna.prod_cta": {"en": "See the production station →","pt": "Ver a estação de produção →","zh": "查看生产站 →"},"social.dm_t": {"en": "The dual mission","pt": "A dupla missão","zh": "双重使命"},"social.eco_sys": {"en": "Not just a rehabilitation centre: an autonomous ecosystem — energy, local maintenance workshops, medical follow-up and AI-assisted rehabilitation.","pt": "Não é apenas um centro de reabilitação: é um ecossistema autónomo — energia, oficinas de manutenção local, acompanhamento médico e reabilitação assistida por IA.","zh": "不只是一个康复中心：而是一个自主生态系统——能源、本地维修工坊、医疗随访，以及人工智能辅助的康复。"},"social.dm1t": {"en": "Rehabilitate and restore autonomy","pt": "Reabilitar e devolver a autonomia","zh": "康复与恢复自主"},"social.dm1d": {"en": "Let people with spinal cord injuries or motor disabilities access advanced robotic rehabilitation, normally reserved for the wealthiest clinics.","pt": "Permitir que pessoas com lesões medulares ou deficiências motoras acedam a reabilitação robótica de ponta, normalmente reservada às clínicas mais ricas.","zh": "让脊髓损伤或运动障碍者获得先进的机器人康复——这通常只有最富裕的诊所才提供。"},"social.dm2t": {"en": "Train on site","pt": "Formar no local","zh": "就地培养"},"social.dm2d": {"en": "Build a local skills hub around robotic maintenance, electronics and AI, so the Isle lives by and for local talent.","pt": "Criar um polo de competências locais em manutenção robótica, eletrónica e IA, para que a Ilha viva pelos e para os talentos locais.","zh": "围绕机器人维护、电子与人工智能建立本地能力中心，让岛屿依靠本地人才、也为了本地人才而运转。"},"social.rep_t": {"en": "A replicable NGO model","pt": "Um modelo de ONG replicável","zh": "可复制的非政府组织模式"},"social.rep_d": {"en": "Madagascar is the first stone. Once the Isle is proven and running, its architecture — software, hardware and human — can be duplicated in other territories.","pt": "Madagascar é a primeira pedra. Uma vez validada e afinada a Ilha, a sua arquitetura — software, hardware e humana — poderá ser duplicada noutros territórios.","zh": "马达加斯加是第一块基石。一旦岛屿得到验证并运转顺畅，其软件、硬件与人的架构便可复制到其他地区。"},"social.badge": {"en": "🌍 THE ULTIMATE GOAL","pt": "🌍 O OBJETIVO FINAL","zh": "🌍 终极目标"},"social.titre": {"en": "The Integrated Isle","pt": "A Ilha Integrada","zh": "综合之岛"},"social.lead": {"en": "This is not a humanitarian centre: it is a replicable economic, technological and social model.","pt": "Não é um centro humanitário: é um modelo económico, tecnológico e social replicável.","zh": "这不是一个人道中心：而是一个可复制的经济、技术与社会模式。"},"social.chapo": {"en": "Not a hospital, not a farm, not a workshop, not a school, not a hotel, not a shop: an autonomous integrated ecosystem. A place where people rehabilitate, cultivate and build — and where children with disabilities and women are not beneficiaries but the builders of their own future.","pt": "Nem hospital, nem fazenda, nem oficina, nem escola, nem hotel, nem loja: um ecossistema integrado autónomo. Um lugar onde se reabilita, se cultiva e se fabrica — e onde as crianças com deficiência e as mulheres não são beneficiárias, mas construtoras do seu próprio futuro.","zh": "不是医院，不是农场，不是工坊，不是学校，不是旅馆，也不是商店：一个自主的综合生态系统。在这里康复、耕作、制造——残疾儿童与女性不是受助者，而是自己未来的建造者。"},"social.devise": {"en": "One person plus one trade equals one family saved!","pt": "Uma pessoa mais um ofício é igual a uma família salva!","zh": "一个人加一门手艺，等于一个家庭得救！"},"social.m1t": {"en": "A model, not a place","pt": "Um modelo, não um lugar","zh": "一个模式，而非一个地点"},"social.m1d": {"en": "The Integrated Isle combines two complementary approaches: scientific excellence and neuro-rehabilitation inspired by Dr Miguel Nicolelis's Institute, and agricultural, craft and economic autonomy carried by the Songhaï Centre model.","pt": "A Ilha Integrada associa duas abordagens complementares: a excelência científica e a neuro-reabilitação inspiradas no Instituto do Dr. Miguel Nicolelis, e a autonomia agrícola, artesanal e económica do modelo do Centro Songhaï.","zh": "综合之岛结合两种互补路径：受 Miguel Nicolelis 博士研究所启发的科学卓越与神经康复，以及由 Songhaï 中心模式承载的农业、手工艺与经济自主。"},"social.m1d2": {"en": "Science develops the technical solutions. Farming, training and production build autonomy. What must replicate from one territory to the next is not a building: it is a method, an organisation and an ecosystem.","pt": "A ciência desenvolve as soluções técnicas. A agricultura, a formação e a produção constroem a autonomia. O que deve replicar-se de um território para outro não é um edifício: é um método, uma organização e um ecossistema.","zh": "科学开发技术方案；农业、培训与生产建立自主。要在不同地区之间复制的不是一座建筑，而是一套方法、一种组织和一个生态系统。"},"social.m2t": {"en": "First pilot: Madagascar","pt": "Primeiro piloto: Madagascar","zh": "首个试点：马达加斯加"},"social.m2d": {"en": "A local team already exists. The project's architect lived in Madagascar in 2015 and again in 2024: the project does not start from a theoretical discovery of the territory, it rests on field experience and established relationships. The goal is to build with local actors, not to impose an outside model.","pt": "Uma equipa local já existe. O arquiteto do projeto viveu em Madagascar em 2015 e em 2024: o projeto não parte de uma descoberta teórica do território, apoia-se numa experiência de campo e em relações estabelecidas. O objetivo é construir com os atores locais, não impor um modelo exterior.","zh": "当地团队已经存在。项目建筑师 2015 年与 2024 年都在马达加斯加生活：项目不是对这片土地的理论发现，而是建立在实地经验与既有关系之上。目标是当地人共同建造，而不是强加外来模式。"},"social.m3t": {"en": "Inclusion, education, emancipation","pt": "Inclusão, educação, emancipação","zh": "包容、教育、赋能"},"social.m3d": {"en": "Children with disabilities and women are at the heart of the project: the whole centre is organised around that priority. Access to education, rehabilitation, vocational training and employment must let each person become gradually autonomous and take part in building their territory.","pt": "As crianças com deficiência e as mulheres estão no centro do projeto: todo o centro está organizado em torno dessa prioridade. O acesso à educação, à reabilitação, à formação profissional e ao emprego deve permitir a cada um tornar-se progressivamente autónomo e participar na construção do seu território.","zh": "残疾儿童与女性是项目核心：整个中心围绕这一优先事项组织。教育、康复、职业培训与就业的机会，应让每个人逐步走向自主，并参与自己土地的建设。"},"social.actes_t": {"en": "The road so far — from acts to achievements","pt": "O caminho percorrido — dos atos às realizações","zh": "走过的路——从各幕到成果"},"social.rbtt": {"en": "2006 — The reboot","pt": "2006 — O reboot","zh": "2006 — 重启"},"social.rbtd": {"en": "An accident. One life stops, another begins. Not just a step: the hinge that redefines the whole trajectory.","pt": "Um acidente. Uma vida termina, outra começa. Não é uma simples etapa: é a dobradiça que redefine toda a trajetória.","zh": "一场事故。一种生活结束，另一种开始。这不是一个简单的阶段，而是重新定义整条轨迹的转折点。"},"social.a0t": {"en": "Act 0 — The spark","pt": "Ato 0 — A faísca","zh": "第 0 幕——火花"},"social.a0d": {"en": "12 June 2014, World Cup, São Paulo. A paraplegic patient kicks off with the help of an exoskeleton developed within Dr Miguel Nicolelis's project. Millions watch; for the project's architect it becomes a decision: to devote his life to making this technology accessible.","pt": "12 de junho de 2014, Copa do mundo, São Paulo. Um paciente paraplégico dá o pontapé inicial com a ajuda de um exoesqueleto desenvolvido no projeto do Dr. Miguel Nicolelis. Milhões veem; para o arquiteto do projeto torna-se uma decisão: dedicar a vida a tornar esta tecnologia acessível.","zh": "2014 年 6 月 12 日，世界杯，圣保罗。一位截瘫患者在 Miguel Nicolelis 博士项目研发的外骨骼帮助下开球。数百万人看见；对项目建筑师而言，这成为一个决定：把一生用来让这项技术可被获得。"},"social.a1t": {"en": "Act 1 — The wave","pt": "Ato 1 — A onda","zh": "第 1 幕——浪潮"},"social.a1d": {"en": "Artificial intelligence arrives and opens a new field of possibilities. A conviction takes shape: assemble the skills, tools and resources needed to build RealiaStation, the project's first computing infrastructure. The compute machine first, the rest after.","pt": "A inteligência artificial chega e abre um novo campo de possibilidades. Uma convicção toma forma: reunir as competências, ferramentas e recursos necessários para construir a RealiaStation, a primeira infraestrutura informática do projeto. A máquina de cálculo primeiro, o resto depois.","zh": "人工智能到来，打开新的可能性。一个信念成形：汇聚所需的能力、工具与资源，建造 RealiaStation——项目的第一套计算基础设施。先造算力，其余随后。"},"social.a2t": {"en": "Act 2 — Self-taught","pt": "Ato 2 — O autodidatismo","zh": "第 2 幕——自学"},"social.a2d": {"en": "A long period of self-directed learning comes to an end. Accumulated knowledge becomes a method. The method becomes architecture. The architecture starts turning into concrete achievements.","pt": "Um longo período de aprendizagem autónoma chega ao fim. O conhecimento acumulado torna-se método. O método torna-se arquitetura. A arquitetura começa a transformar-se em realizações concretas.","zh": "漫长的自主学习期走向终点。积累的知识成为方法，方法成为架构，架构开始转变为具体成果。"},"social.a3t": {"en": "Act 3 — Intelligence and the virtual","pt": "Ato 3 — A inteligência e o virtual","zh": "第 3 幕——智能与虚拟"},"social.a3d": {"en": "The project enters its first operational phase: build the digital twin and the AI systems meant to analyse brain and muscle signals. The personal journey meets the technology roadmap here.","pt": "O projeto entra na sua primeira fase operacional: desenvolver o gémeo digital e os sistemas de IA destinados a analisar os sinais cerebrais e musculares. O percurso pessoal encontra aqui o roteiro tecnológico.","zh": "项目进入第一个执行阶段：开发数字孪生，以及用于分析大脑与肌肉信号的人工智能系统。个人历程在此与技术路线图汇合。"},"social.phases_t": {"en": "The project's three phases","pt": "As três fases do projeto","zh": "项目的三个阶段"},"social.ph1t": {"en": "Phase 1 — Intelligence and the virtual","pt": "Fase 1 — A inteligência e o virtual","zh": "第一阶段——智能与虚拟"},"social.ph1d": {"en": "Finish the digital twin and the AI that processes and interprets brain and muscle signals. Build the software environment, the simulation tools and the technical foundations of the future Exo-Robot. This first phase lays the project's foundations.","pt": "Concluir o gémeo digital e a IA destinada a tratar e interpretar os sinais cerebrais e musculares. Construir o ambiente de software, as ferramentas de simulação e as bases técnicas do futuro Exorrobô. Esta primeira fase lança as fundações do projeto.","zh": "完成数字孪生，以及用于处理与解读大脑和肌肉信号的人工智能。搭建软件环境、仿真工具与未来外骨骼机器人的技术基础。这一阶段奠定项目根基。"},"social.ph2t": {"en": "Phase 2 — Hardware and funding","pt": "Fase 2 — O hardware e os financiamentos","zh": "第二阶段——硬件与资金"},"social.ph2d": {"en": "Raise the funding, then go to China to meet suppliers, identify industrial partners and work directly at the source of the equipment.","pt": "Mobilizar os financiamentos e ir à China para encontrar fornecedores, identificar parceiros industriais e trabalhar diretamente na origem dos equipamentos.","zh": "筹集资金，然后前往中国，对接供应商、寻找工业伙伴，直接在生产源头工作。"},"social.ph2l": {"en": "Goals: develop industrial partnerships · acquire the Integrated Isle's equipment · design and build the physical Exo-Robot prototype · equip the FabLab and the first site's technical infrastructure.","pt": "Objetivos: desenvolver parcerias industriais · adquirir os equipamentos da Ilha Integrada · conceber e fabricar o protótipo físico do Exorrobô · equipar o FabLab e as infraestruturas do primeiro site.","zh": "目标：发展工业伙伴关系 · 采购综合之岛所需设备 · 设计并制造外骨骼机器人实体原型 · 装备 FabLab 与首个站点的技术设施。"},"social.ph3t": {"en": "Phase 3 — The Integrated Isle in Madagascar","pt": "Fase 3 — A Ilha Integrada em Madagascar","zh": "第三阶段——马达加斯加的综合之岛"},"social.ph3d": {"en": "Set up and start the first replicable NGO model in Madagascar. Strategic proximity to Asia eases supply chains. The first site becomes a ground for experimentation, training, production and transmission, before any duplication.","pt": "Implantar e iniciar o primeiro modelo de ONG replicável em Madagascar. A proximidade estratégica da Ásia facilita os circuitos de abastecimento. O primeiro site torna-se terreno de experimentação, formação, produção e transmissão, antes de uma eventual duplicação.","zh": "在马达加斯加落地并启动首个可复制的非政府组织模式。靠近亚洲，便于供应链。首个站点成为试验、培训、生产与传承的场所，之后再考虑复制。"},"social.fin_t": {"en": "How to fund the project durably","pt": "Como financiar o projeto de forma durável","zh": "如何长期筹资"},"social.fin_lead": {"en": "Build an economic ecosystem able to contribute progressively to funding its own social activities.","pt": "Construir um ecossistema económico capaz de contribuir progressivamente para o financiamento das suas próprias atividades sociais.","zh": "建立一个经济生态系统，逐步为其自身的社会活动提供资金。"},"social.f1t": {"en": "Import-export and circular logistics","pt": "Importação-exportação e logística circular","zh": "进出口与循环物流"},"social.f1d": {"en": "A supply chain between Asia, Madagascar and Europe. Equipment and technology arrive in optimised containers; return trips add value to local production and open commercial outlets.","pt": "Um circuito de abastecimento entre a Ásia, Madagascar e a Europa. Equipamentos e tecnologias chegam em contentores otimizados; os circuitos de retorno valorizam a produção local e criam saídas comerciais.","zh": "在亚洲、马达加斯加与欧洲之间建立供应链。设备与技术以优化集装箱运达；回程把本地产品带出去，创造商业出口。"},"social.f2t": {"en": "Farm cooperative and fruit bank","pt": "Cooperativa agrícola e banco de frutas","zh": "农业合作社与水果银行"},"social.f2d": {"en": "Grow locally, then sort, process, dehydrate, store and sell. The fruit bank adds value to harvests, limits losses and keeps more value in the territory.","pt": "Produzir localmente e depois triar, transformar, desidratar, armazenar e comercializar. O banco de frutas valoriza as colheitas, limita as perdas e retém mais valor no território.","zh": "本地种植，然后分选、加工、脱水、储存与销售。水果银行让收成增值，减少损耗，把更多价值留在本地。"},"social.f3t": {"en": "FabLab for people with disabilities","pt": "FabLab para pessoas com deficiência","zh": "残障人士创客工坊"},"social.f3d": {"en": "An adapted fabrication and repair workshop: 3D printing, prosthetics, orthotics, technical parts, wheelchair repair and adaptation. The FabLab becomes a tool for production, training and local innovation.","pt": "Uma oficina de fabrico e reparação adaptada: impressão 3D, próteses, ortóteses, peças técnicas, reparação e adaptação de cadeiras de rodas. O FabLab torna-se uma ferramenta de produção, formação e inovação local.","zh": "一个适配的制造与维修工坊：3D 打印、假肢、矫形器、技术零件、轮椅维修与改装。FabLab 成为生产、培训与本地创新的工具。"},"social.f4t": {"en": "AI, LunaGalaxie and shop","pt": "IA, LunaGalaxie e loja","zh": "人工智能、LunaGalaxie 与商店"},"social.f4d": {"en": "A complementary digital activity: content, media, digital products, audience, affiliation and shop. Virtual revenue helps fund the real.","pt": "Uma atividade digital complementar: conteúdos, média, produtos digitais, audiência, afiliação e loja. A receita do virtual ajuda a financiar o real.","zh": "一项补充性的数字业务：内容、媒体、数字产品、受众、联盟推广与商店。虚拟收入帮助资助现实。"},"social.sol_t": {"en": "On site: inclusion, education and emancipation","pt": "No local: inclusão, educação e emancipação","zh": "在现场：包容、教育与赋能"},"social.sol_d": {"en": "The Integrated Isle does not merely host people: it gives them the means to learn, produce and take responsibility. Children with disabilities get an accessible environment, adapted support and training opportunities. Women gain access to educational and professional paths leading to employment, entrepreneurship and the management of local activities. The whole centre becomes a place of transmission and cooperation.","pt": "A Ilha Integrada não se limita a acolher pessoas: dá-lhes meios para aprender, produzir e assumir responsabilidades. As crianças com deficiência têm um ambiente acessível, acompanhamento adaptado e oportunidades de formação. As mulheres acedem a percursos educativos e profissionais que as podem levar ao emprego, ao empreendedorismo e à gestão das atividades locais. O centro inteiro torna-se um lugar de transmissão e cooperação.","zh": "综合之岛不只是接纳人：它给人学习、生产与承担责任的手段。残疾儿童获得无障碍环境、适配支持与培训机会。女性获得教育与职业路径，通向就业、创业与本地活动的管理。整个中心成为传承与合作的场所。"},"social.sol_c1t": {"en": "Cooperative and fruit bank","pt": "Cooperativa e banco de frutas","zh": "合作社与水果银行"},"social.sol_c1d": {"en": "Local producers bring their harvests. Teams handle sorting, packing, processing and storage under adapted infrastructure.","pt": "Produtores locais trazem as suas colheitas. As equipas garantem a triagem, o acondicionamento, a transformação e o armazenamento em infraestruturas adaptadas.","zh": "本地生产者送来收成。团队在适配设施下完成分选、包装、加工与储存。"},"social.sol_c2t": {"en": "FabLab","pt": "FabLab","zh": "创客工坊"},"social.sol_c2d": {"en": "A workshop equipped with 3D printers and fabrication tools to produce, adapt and repair equipment for people with disabilities.","pt": "Uma oficina equipada com impressoras 3D e ferramentas de fabrico permite produzir, adaptar e reparar equipamentos para pessoas com deficiência.","zh": "配备 3D 打印机与制造工具的工坊，为残障人士生产、改装与维修设备。"},"social.amb_t": {"en": "A concrete project, an evolving ambition","pt": "Um projeto concreto, uma ambição evolutiva","zh": "具体的项目，持续演进的雄心"},"social.amb_d": {"en": "The first Isle must prove the model works: inclusion, training, local production, innovation and economic autonomy. Each activity strengthens the others. Every skill acquired must be passed on. Each site prepares the next. The ambition is a network of autonomous structures, adapted to local realities and linked by the same method.","pt": "A primeira Ilha deve demonstrar a viabilidade do modelo: inclusão, formação, produção local, inovação e autonomia económica. Cada atividade reforça as outras. Cada competência adquirida deve poder ser transmitida. Cada site prepara o seguinte. A ambição é uma rede de estruturas autónomas, adaptadas às realidades locais e ligadas pelo mesmo método.","zh": "首座综合之岛必须证明模式可行：包容、培训、本地生产、创新与经济自主。每项活动都强化其他活动；每项获得的技能都必须能传承；每个站点都为下一个做准备。目标是建立一个由同一方法连接的、适配各地现实的自主结构网络。"},"social.close_t": {"en": "Several territories, one commitment","pt": "Vários territórios, um mesmo compromisso","zh": "多个地区，同一份承诺"},"social.close_d": {"en": "Building lasting solutions with the people concerned. Open-source project — research prototype, not a medical device.","pt": "Construir soluções duradouras com as pessoas envolvidas. Projeto open source — protótipo de investigação, não dispositivo médico.","zh": "与相关的人一起建造持久的解决方案。开源项目——研究原型，非医疗器械。"},"social.cta": {"en": "Discover the project and contribute","pt": "Descobrir o projeto e contribuir","zh": "了解项目并参与"},"archi.badge": {"en": "ABOUT","pt": "SOBRE","zh": "关于"},"archi.titre": {"en": "The Architect: a rebirth, a cause, a mission","pt": "O Arquiteto: um renascimento, uma causa, uma missão","zh": "建筑师：一次重生，一项事业，一个使命"},"archi.intro": {"en": "This is only a summary. I have lived several lives, and I do not intend to make a book of them here — my past adventures will rather serve as raw material to enrich LunaGalaxie's universe and stories. The essential is elsewhere: after an extraordinary path, I have finally found my purpose, my project, my cause. It is now my mission, to the end.","pt": "Este relato é só um resumo. Vivi várias vidas e não pretendo fazer um livro disso aqui — minhas aventuras passadas servirão antes como matéria-prima para enriquecer o universo e as histórias de LunaGalaxie. O essencial está em outro lugar: depois de um caminho fora do comum, finalmente encontrei meu propósito, meu projeto, minha causa. É agora minha missão, até o fim.","zh": "这只是一份概要。我活过好几辈子，不打算在这里写成书——过往的冒险会成为素材，用来丰富 LunaGalaxie 的宇宙与故事。要紧的在别处：走过一条不寻常的路之后，我终于找到了目标、项目和事业。从今往后，这就是我的使命，直到最后。"},"archi.h1": {"en": "1. Roots: the school of the forest and inclusion","pt": "1. Raízes: a escola da floresta e da inclusão","zh": "1. 根：森林与包容的学校"},"archi.p1": {"en": "Born in France, I left at the age of 4. My mother, a Sorbonne student in May 68, chose to turn her back on the comfort of Paris's 16th arrondissement to take her children to the Caribbean, then to French Guiana, where she became a specialised primary teacher for children in difficulty. At her side, from the age of 15, I learned the value of inclusion and of passing things on.","pt": "Nasci na França e saí aos 4 anos. Minha mãe, estudante da Sorbonne em maio de 68, escolheu virar as costas ao conforto do 16º arrondissement de Paris para levar os filhos ao Caribe e depois à Guiana Francesa, onde se tornou professora especializada em crianças com dificuldades. Ao lado dela, desde os 15 anos, aprendi o valor da inclusão e da transmissão.","zh": "我出生在法国，四岁离开。母亲是 1968 年五月风暴中的索邦学生，她选择背对巴黎十六区的舒适生活，带孩子去加勒比，再去了法属圭亚那，在那里成为面向困难儿童的特教教师。从十五岁起，我在她身边学到了包容与传承的价值。"},"archi.p2": {"en": "French Guiana forged my character: father of a first son the day before my 19th birthday with an Amerindian woman, I lived off the river and the forest — first fishing, then gold panning alongside Brazilians, before moving to a metal detector (MineLab) to work cleanly without polluting the rivers, while completing a two-year technical diploma in tourism and field work.","pt": "A Guiana formou meu caráter: pai de um primeiro filho na véspera dos 19 anos com uma mulher indígena, vivi do rio e da floresta — primeiro a pesca, depois o garimpo ao lado dos brasileiros, antes de passar ao detector de metais (MineLab) para trabalhar limpo sem poluir os rios, concluindo ao mesmo tempo uma formação técnica em turismo e ofícios de campo.","zh": "圭亚那塑造了我的性格：十九岁生日前夜，我与一位美洲原住民女性有了第一个儿子；我以河流和森林为生——先捕鱼，后与巴西人一起淘金，再改用金属探测器（MineLab），只为干净作业、不污染河流，同时完成了旅游与野外技能的两年制技术文凭。"},"archi.h2": {"en": "2. 31 October: the second birth","pt": "2. 31 de outubro: o segundo nascimento","zh": "2. 10 月 31 日：第二次出生"},"archi.p3": {"en": "The same year took my father in spring and gave me my second son in autumn, born of my union with a Matawai woman. The following year, on 31 October — Halloween night — an accident left me a complete tetraplegic.","pt": "Um mesmo ano levou meu pai na primavera e me deu meu segundo filho no outono, nascido da minha união com uma mulher Matawai. No ano seguinte, em 31 de outubro — noite de Halloween — um acidente me deixou tetraplégico completo.","zh": "同一年，春天带走了父亲，秋天送来了第二个儿子——他是我与一位 Matawai 女性的孩子。次年 10 月 31 日，万圣节之夜，一场事故让我成为完全性四肢瘫痪。"},"archi.p4": {"en": "I consider that day a new birth. My youngest was only 8 months old: no question of spending three years shut in a rehabilitation centre away from him. After only 8 months, I left against medical advice to find him again and fight on my own.","pt": "Considero esse dia um novo nascimento. Meu caçula tinha apenas 8 meses: nada de passar três anos fechado num centro de reabilitação longe dele. Depois de apenas 8 meses, saí contra o parecer médico para reencontrá-lo e lutar por mim mesmo.","zh": "我把那一天当作新的诞生。小儿子当时才八个月：绝不可能在康复中心关上三年、离他那么远。仅八个月后，我违背医嘱出院，去到他身边，靠自己搏一把。"},"archi.p5": {"en": "Life kept testing me — I lost my mother shortly after — but I moved forward: by my 18th year of disability I had regained enough autonomy to travel alone from Guiana to Madagascar, a land that marked me deeply. Seven years after the accident, as my son approached his 7th birthday, I took the difficult decision to separate from his mother: she had always been a precious support, but she sheltered me too much — I had to live alone to conquer full autonomy.","pt": "A vida continuou a me testar — perdi minha mãe pouco depois — mas avancei: aos 18 anos de deficiência, tinha autonomia suficiente para partir sozinho da Guiana até Madagascar, uma terra que me marcou profundamente. Sete anos após o acidente, quando meu filho se aproximava dos 7 anos, tomei a decisão difícil de me separar da mãe dele: ela sempre foi um apoio precioso, mas me protegia demais — eu precisava viver só para conquistar a autonomia plena.","zh": "生活继续考验我——不久后母亲去世——但我向前走：残疾第十八年，我已恢复到能独自从圭亚那前往马达加斯加，那片土地深深影响了我。事故七年后，儿子将满七岁时，我做出艰难决定，与他的母亲分开：她一直是珍贵的支撑，却把我护得太紧——我必须独居，才能夺回完整的自主。"},"archi.h3": {"en": "3. The 2014 spark and the AI turn (2024–2026)","pt": "3. A faísca de 2014 e a virada da IA (2024–2026)","zh": "3. 2014 年的火花与人工智能转折（2024—2026）"},"archi.p6": {"en": "A year after that new start, I see the World Cup in Brazil kicked off by a paraplegic patient thanks to Dr Miguel Nicolelis's exoskeleton. The idea of Neuro-Exo is born that day. For years it matures while I train young people in farming on my land in Guiana.","pt": "Um ano depois desse novo começo, vejo a Copa do Mundo no Brasil ser aberta por um paciente paraplégico graças ao exoesqueleto do Dr. Miguel Nicolelis. A ideia do Neuro-Exo nasce naquele dia. Por anos amadurece enquanto formo jovens na agricultura no meu terreno na Guiana.","zh": "新起点一年后，我看到巴西世界杯由一位截瘫患者借 Miguel Nicolelis 博士的外骨骼开球。Neuro-Exo 的想法就在那天诞生。此后多年，它在我于圭亚那种地、带年轻人的日子里慢慢成熟。"},"archi.p7": {"en": "Then artificial intelligence arrives. I ride the wave, learn, and relaunch my project. Late 2024, with my eldest son's help and a nudge from providence, we raise the funds for my compute machine; I leave Guiana, stop at my son's to order the parts, and fly to Madagascar — with a two-day stopover in Ethiopia — where I stay six months with my local team.","pt": "Depois chega a inteligência artificial. Surfo a onda, me informo e relanço meu projeto. No fim de 2024, com a ajuda do meu filho mais velho e um empurrão da providência, reunimos os fundos para a máquina de cálculo; deixo a Guiana, passo na casa do meu filho para encomendar as peças e voo para Madagascar — com escala de dois dias na Etiópia — onde fico seis meses com minha equipe local.","zh": "随后人工智能到来。我乘势而上，边学边重启项目。2024 年底，在大儿子帮助与天意的推动下，我们凑齐了计算主机的资金；我离开圭亚那，去儿子那里下单零件，然后飞往马达加斯加——在埃塞俄比亚中转两天——在那里与本地团队待了六个月。"},"archi.p8": {"en": "Late 2025, back in Guiana after a month in France, I — who had never really opened a Linux terminal — dive into it seriously to build the project's software architecture. Late 2026 — my 20th year of rebirth, in Brazil — I leave on an R&D expedition toward my destiny, on the very lands where the spark was born, to build the prototypes, officially found our NGO and deploy our Integrated Isles for disabled children and women.","pt": "No fim de 2025, de volta à Guiana após um mês na França, eu — que nunca tinha aberto de verdade um terminal Linux — mergulho a sério para construir a arquitetura de software do projeto. No fim de 2026 — meus 20 anos de renascimento, no Brasil — parto em expedição de P&D rumo ao meu destino, nas terras onde a faísca nasceu, para concretizar os protótipos, fundar oficialmente nossa ONG e implantar as Ilhas Integradas a serviço de crianças com deficiência e mulheres.","zh": "2025 年底，在法国待了一个月后回到圭亚那，我这个从未真正打开过 Linux 终端的人，认真钻了进去，构建项目的软件架构。2026 年底——我重生的第二十年，在巴西——我启程进行研发远征，回到火花诞生的土地，把原型做出来，正式成立我们的非政府组织，并部署服务残疾儿童与女性的综合之岛。"},"archi.photo_leg": {"en": "The Architect — [IMG_ARCHITECTE]","pt": "O Arquiteto — [IMG_ARCHITECTE]","zh": "建筑师——[IMG_ARCHITECTE]"},"archi.cta": {"en": "See the social mission →","pt": "Ver a missão social →","zh": "查看社会使命 →"},"cabinet.badge": {"en": "INDEPENDENT PRACTICE","pt": "ATIVIDADE INDEPENDENTE","zh": "独立业务"},"cabinet.etiq": {"en": "Professional activity & consulting","pt": "Atividade profissional e consultoria","zh": "专业活动与咨询"},"cabinet.titre": {"en": "The Architect's Study Cabinet","pt": "O Gabinete de Estudos do Arquiteto","zh": "建筑师的顾问工作室"},"cabinet.intro": {"en": "From designing tailor-made tourism circuits to architecting AI agents: the craft is the same. Mapping flows, anticipating human needs and orchestrating complex systems to erase everyday friction.","pt": "Do desenho de circuitos turísticos sob medida à arquitetura de agentes de IA: o ofício é o mesmo. Mapear fluxos, antecipar necessidades humanas e orquestrar sistemas complexos para apagar as fricções do dia a dia.","zh": "从量身定制的旅游线路设计，到人工智能智能体的架构：手艺从未改变。梳理流线、预判人的需求、编排复杂系统，抹去日常的摩擦。"},"cabinet.ethique_t": {"en": "A clear boundary","pt": "Uma fronteira clara","zh": "一条清晰的界线"},"cabinet.ethique": {"en": "Donations and LunaGalaxie revenue fund only the social mission and NeuroExo's exoskeleton R&D. The Study Cabinet is my independent commercial activity: I put the same architectural know-how at the service of professionals to earn my living honestly, without ever touching the mission's funds.","pt": "As doações e a receita da LunaGalaxie financiam exclusivamente a missão social e a P&D do exoesqueleto NeuroExo. O Gabinete de Estudos é minha atividade comercial independente: coloco esse mesmo savoir-faire de arquiteto a serviço dos profissionais para ganhar a vida com honestidade, sem nunca tocar nos fundos da missão.","zh": "捐赠与 LunaGalaxie 的收入只用于社会使命和 NeuroExo 外骨骼的研发。顾问工作室是我独立的商业活动：我把同样的架构手艺用于服务专业人士，靠诚实劳动谋生，绝不动用使命的资金。"},"cabinet.domaine_t": {"en": "Areas of work","pt": "As áreas de atuação","zh": "服务领域"},"cabinet.c1t": {"en": "Audit & field study","pt": "Auditoria e estudo de campo","zh": "审计与实地调研"},"cabinet.c1s": {"en": "On site or remote","pt": "No local ou à distância","zh": "现场或远程"},"cabinet.c1d": {"en": "A real observation of your operational friction. No useless technical jargon: I analyse your lost time, missed calls and repetitive tasks to design a solution that fits your actual trade.","pt": "Observação real das suas fricções operacionais. Sem jargão técnico inútil: analiso suas perdas de tempo, chamadas perdidas e tarefas repetitivas para desenhar uma solução adaptada à sua realidade profissional.","zh": "实地观察你的运营摩擦。不说没用的术语：我分析你浪费的时间、漏接的电话和重复劳动，画出贴合你行业现实的方案。"},"cabinet.c2t": {"en": "Agentic architectures & WhatsApp","pt": "Arquiteturas agênticas e WhatsApp","zh": "智能体架构与 WhatsApp"},"cabinet.c2s": {"en": "Tailor-made agents","pt": "Agentes sob medida","zh": "量身定制的智能体"},"cabinet.c2d": {"en": "Tailor-made AI agents for overstretched professionals (dentists, lawyers, guesthouses, craftspeople). Automated appointments, request qualification, client follow-up and integrated payments (Pix, calendars, records).","pt": "Concepção de agentes de IA sob medida para profissionais sobrecarregados (dentistas, advogados, pousadas, artesãos). Gestão automática de agendamentos, qualificação de pedidos, acompanhamento do cliente e pagamentos integrados (Pix, agendas, prontuários).","zh": "为疲于应付的专业人士（牙医、律师、民宿、手艺人）量身设计智能体：自动管理预约、筛选需求、跟进客户并集成支付（Pix、日程、档案）。"},"cabinet.c3t": {"en": "IoT bridges & connected spaces","pt": "Pontes IoT e ambientes conectados","zh": "物联网网关与互联空间"},"cabinet.c3s": {"en": "From digital to physical","pt": "Do digital ao físico","zh": "从数字到物理"},"cabinet.c3d": {"en": "Connecting artificial intelligence to the physical world: smart energy control (air conditioning), connected cameras, accessible home automation (for reduced mobility) and real-time alerts for small organisations.","pt": "Conexão entre a inteligência artificial e o mundo físico: controle inteligente de energia (ar-condicionado), câmeras conectadas, domótica acessível (mobilidade reduzida) e alertas em tempo real para pequenas estruturas.","zh": "把人工智能接到物理世界：能耗智能调控（空调）、联网摄像头、无障碍家居（行动不便者）以及面向小型机构实时告警。"},"cabinet.contact_t": {"en": "Get in touch","pt": "Entrar em contato","zh": "联系"},"cabinet.contact": {"en": "Write three lines about your situation: I answer within 48 hours with a first reading, free and without commitment.","pt": "Escreva três linhas sobre a sua situação: respondo em 48 horas com uma primeira leitura, gratuita e sem compromisso.","zh": "用三行话描述你的处境，我在 48 小时内回复一份初步判断，免费且不附带任何承诺。"},"cabinet.cta": {"en": "Request a study / Get in touch","pt": "Solicitar um estudo / Entrar em contato","zh": "申请调研 / 联系我"},"cabinet.c4t": {"en": "On-demand services & feasibility studies","pt": "Serviços sob demanda e estudos de viabilidade","zh": "按需服务与可行性研究"},"cabinet.c4s": {"en": "Framing before deciding","pt": "Enquadramento antes de decidir","zh": "决策前的界定"},"cabinet.c4d": {"en": "One precise question, one costed answer: technical and economic feasibility, scoping the need, choosing the tools, estimating workload and cost. For projects nobody has dared to frame yet.","pt": "Uma pergunta precisa, uma resposta com números: viabilidade técnica e econômica, enquadramento da necessidade, escolha das ferramentas, estimativa de carga e custo. Para projetos que ninguém ainda ousou enquadrar.","zh": "一个明确的问题，一份带数字的答复：技术与经济可行性、需求界定、工具选型、工作量与成本估算。给那些还没人敢界定的项目。"},"cabinet.pmr_t": {"en": "Field studies & accessibility for reduced mobility","pt": "Estudos de campo e acessibilidade para mobilidade reduzida","zh": "实地调研与无障碍（行动不便者）"},"cabinet.pmr_d": {"en": "I come to you and measure what actually blocks: passage widths, thresholds, turning circles, grip heights, lighting, the route from door to door. The report gives priorities and cost ranges, not a list of off-the-shelf prescriptions. My wheelchair is my measuring instrument: what I cannot get through, your customers cannot get through either.","pt": "Vou até você e meço o que realmente bloqueia: largura das passagens, soleiras, raios de giro, alturas de alcance, iluminação, o caminho de porta a porta. O relatório traz prioridades e ordens de custo, não uma lista de prescrições fora da realidade. Minha cadeira é meu instrumento de medida: o que eu não passo, seus clientes também não passam.","zh": "我上门实测真正卡住的地方：通道宽度、门槛、回转半径、可及高度、照明、从门到门的通行路线。报告给出优先级与成本区间，而不是一份脱离现场的规范清单。我的轮椅就是量具：我过不去的地方，你的客户也过不去。"},"cabinet.pmr_puces": {"en": "Thresholds and steps|Passage widths|Turning circles|Grip heights|Lighting and contrast|Outdoor route","pt": "Soleiras e desníveis|Larguras de passagem|Raios de giro|Alturas de alcance|Iluminação e contraste|Percurso externo","zh": "门槛与高差|通道宽度|回转半径|可及高度|照明与对比|室外通行路线"},"cabinet.pmr_leg": {"en": "A threshold is measured, not guessed","pt": "Uma soleira se mede, não se adivinha","zh": "门槛要量，不能猜"},"cabinet.figure_leg": {"en": "The cabinet: map, connect, lighten","pt": "O gabinete: mapear, conectar, aliviar","zh": "工作室：梳理、连接、减负"},"wish.badge": {"en": "🚧 WORK IN PROGRESS — PHASE 1","pt": "🚧 EM OBRAS — FASE 1","zh": "🚧 建设中 — 第一阶段"},"wish.titre": {"en": "The lab's wishlist","pt": "A lista de desejos do laboratório","zh": "实验室心愿单"},"wish.lead": {"en": "Four components, not a pool. If you want to fund a precise item, you know exactly what your money buys — and what it unlocks.","pt": "Quatro componentes, não um bolo. Se quiser financiar um item exato, sabe exatamente o que seu dinheiro compra — e o que destrava.","zh": "四个部件，而不是一笔糊涂账。若你想资助某件具体的东西，你清楚钱买了什么，又打开了什么。"},"wish.l1": {"en": "OpenBCI Ultracortex Mark IV EEG headset + Cyton board (8 channels)","pt": "Capacete EEG OpenBCI Ultracortex Mark IV + placa Cyton (8 canais)","zh": "OpenBCI Ultracortex Mark IV 脑电帽 + Cyton 板（8 通道）"},"wish.l1d": {"en": "Dry electrodes: read brain waves without scalp preparation.","pt": "Eletrodos secos: ler ondas cerebrais sem preparar o couro cabeludo.","zh": "干电极：无需准备头皮即可读取脑电。"},"wish.l2": {"en": "MyoWare 2.0 Muscle Sensor kit (SparkFun)","pt": "Kit MyoWare 2.0 Muscle Sensor (SparkFun)","zh": "MyoWare 2.0 肌肉传感器套件（SparkFun）"},"wish.l2d": {"en": "Modular sEMG sensors: capture muscle micro-signals, in the field as on the bench.","pt": "Sensores sEMG modulares: captar micro-sinais musculares, no campo e na bancada.","zh": "模块化 sEMG 传感器：在野外与试验台上捕捉肌肉微信号。"},"wish.l3": {"en": "ESP32-S3-DevKitC-1 boards (set of 3)","pt": "Placas ESP32-S3-DevKitC-1 (kit de 3)","zh": "ESP32-S3-DevKitC-1 开发板（3 块）"},"wish.l3d": {"en": "Real-time acquisition under 20 ms and low-latency wireless link.","pt": "Aquisição em tempo real abaixo de 20 ms e enlace sem fio de baixa latência.","zh": "20 毫秒内的实时采集与低延迟无线链路。"},"wish.l4": {"en": "Isolated FES module + TENS/EMS electrodes","pt": "Módulo FES isolado + eletrodos TENS/EMS","zh": "隔离式 FES 模块 + TENS/EMS 电极"},"wish.l4d": {"en": "Battery-powered safe functional stimulation: the part that demands serious isolation.","pt": "Estimulação funcional segura a bateria: a parte que exige isolação séria.","zh": "电池供电的安全功能性电刺激：最需要严肃隔离的部分。"},"wish.bouton_amazon": {"en": "See my official Amazon wishlist","pt": "Ver minha lista de desejos oficial na Amazon","zh": "查看我的亚马逊官方心愿单"},"wish.cagnottes": {"en": "Or contribute freely — Ko-fi / Tipeee","pt": "Ou contribuir livremente — Ko-fi / Tipeee","zh": "或自由捐助 —— Ko-fi / Tipeee"},"wish.note": {"en": "Prices are public estimates, shipping excluded. No commission is taken on these purchases: the Amazon link points to my list, not an affiliate cart.","pt": "Os preços são estimativas públicas, sem frete. Nenhuma comissão é cobrada nessas compras: o link da Amazon leva à minha lista, não a um carrinho afiliado.","zh": "价格为公开估价，不含运费。这些购买不收取任何佣金：亚马逊链接指向我的心愿单，而非联盟购物车。"},"boutique.badge": {"en": "🎄 SOLIDARITY SHOP — CHRISTMAS","pt": "🎄 LOJA SOLIDÁRIA — NATAL","zh": "🎄 公益商店 — 圣诞"},"boutique.titre": {"en": "Do your Christmas shopping!","pt": "Faça suas compras de Natal!","zh": "来买圣诞礼物吧！"},"boutique.lead": {"en": "This is not a shopping list for the project. You shop as usual, at the usual price, and the platform pays a commission to fund Neuro-Exo and its future NGO. Zero extra euros for you.","pt": "Não é uma lista de compras para o projeto. Você compra como sempre, pelo preço normal, e a plataforma paga uma comissão para financiar o Neuro-Exo e sua futura ONG. Zero euro a mais para você.","zh": "这不是为项目采购的清单。你照常购物、照常价格，平台支付一笔佣金来资助 Neuro-Exo 及其未来的非政府组织。你不会多花一分钱。"},"boutique.v1": {"en": "High-tech gifts & AI gadgets","pt": "Presentes high-tech e gadgets de IA","zh": "高科技礼物与人工智能小物"},"boutique.v1d": {"en": "For those who want to understand AI by touching it.","pt": "Para quem quer entender IA tocando nela.","zh": "给想通过触摸理解人工智能的人。"},"boutique.v2": {"en": "Maker workshop, electronics & 3D printing","pt": "Oficina maker, eletrônica e impressão 3D","zh": "创客工坊、电子与 3D 打印"},"boutique.v2d": {"en": "Soldering irons, microcontrollers, filament: the project's toolbox.","pt": "Ferros de solda, microcontroladores, filamento: a caixa de ferramentas do projeto.","zh": "烙铁、微控制器、耗材：项目的工具箱。"},"boutique.v3": {"en": "Books, sci-fi & neuroscience","pt": "Livros, ficção científica e neurociência","zh": "书籍、科幻与神经科学"},"boutique.v3d": {"en": "What fed the project, and what will feed it further.","pt": "O que alimentou o projeto e o que ainda vai alimentar.","zh": "曾经滋养项目的东西，以及还将滋养它的东西。"},"boutique.v4": {"en": "Home, toys & family ideas","pt": "Casa, brinquedos e ideias de família","zh": "家居、玩具与家庭灵感"},"boutique.v4d": {"en": "Gifts that have nothing to do with tech — and that's fine.","pt": "Presentes que nada têm a ver com tecnologia — e está ótimo.","zh": "与科技毫无关系的礼物——这样也很好。"},"boutique.enseignes_titre": {"en": "The retailers","pt": "As lojas","zh": "商家"},"boutique.enseignes": {"en": "Buttons enabled as partner accounts get approved.","pt": "Botões ativados conforme as contas de parceiro forem aprovadas.","zh": "随着合作账号通过审核，按钮将陆续启用。"},"boutique.mention": {"en": "As a participant in the affiliate programmes mentioned, Neuro-Exo earns from qualifying purchases, at no additional cost to the buyer.","pt": "Como participante dos programas de afiliação mencionados, o Neuro-Exo recebe comissão sobre compras qualificadas, sem custo adicional para o comprador.","zh": "作为上述联盟计划的参与者，Neuro-Exo 通过符合条件的购买获得收益，买家无需支付任何额外费用。"},"boutique.noel": {"en": "Merry Christmas — and thank you for keeping the project alive by buying what you need.","pt": "Feliz Natal — e obrigado por manter o projeto vivo comprando o que você precisa.","zh": "圣诞快乐——谢谢你买下你需要的东西，让项目继续活着。"},"blueprint.accroche": {"en": "From open source to industry: build the brain before the metal.","pt": "Do open source à indústria: construir o cérebro antes do metal.","zh": "从开源到产业：先造大脑，再造金属。"},"blueprint.et_t": {"en": "The three development steps","pt": "As três etapas de desenvolvimento","zh": "三个发展阶段"},"blueprint.e1t": {"en": "Step 1 — The open-source brain","pt": "Etapa 1 — O cérebro open source","zh": "第一步——开源大脑"},"blueprint.e1s": {"en": "In progress","pt": "Em curso","zh": "进行中"},"blueprint.e1d": {"en": "Designing the NeuroExoAI harness and training on the digital twin. An open software base to prove the Brain-Muscle-Machine loop is reliable, without heavy hardware costs.","pt": "Conceção do arnês NeuroExoAI e treino no gémeo digital. Uma base de software aberta para provar a fiabilidade do ciclo Cérebro-Músculo-Máquina sem custos de hardware elevados.","zh": "设计 NeuroExoAI 束具，并在数字孪生上训练。开源软件基础，用于在不大规模投入硬件的前提下，证明脑—肌—机闭环的可靠性。"},"blueprint.e2t": {"en": "Step 2 — Heading for China","pt": "Etapa 2 — Rumo à China","zh": "第二步——前往中国"},"blueprint.e2s": {"en": "Next","pt": "Próxima","zh": "下一步"},"blueprint.e2d": {"en": "A dedicated raise to go to the source of robotics and electronics. Goal: industrial partnerships, motors and sensors at the best cost, assembly of the first complete physical Exo-Robot prototype and the Integrated Isle's equipment.","pt": "Angariação dedicada para ir à origem da robótica e dos componentes eletrónicos. Objetivo: parcerias industriais, motores e sensores ao melhor custo, montagem do primeiro protótipo físico completo do Exorrobô e dos equipamentos da Ilha Integrada.","zh": "专项募资，直接前往机器人与电子元件的源头。目标：工业合作、以最优成本采购电机与传感器、组装完整的首台外骨骼机器人实体原型及综合之岛设备。"},"blueprint.e3t": {"en": "Step 3 — Deployment & replication","pt": "Etapa 3 — Implantação e replicação","zh": "第三步——部署与复制"},"blueprint.e3s": {"en": "Ahead","pt": "Por vir","zh": "未来"},"blueprint.e3d": {"en": "Commissioning of the first pilot centre in Madagascar, designed as a turnkey model replicable elsewhere in the world.","pt": "Entrada em serviço do primeiro centro-piloto em Madagascar, concebido como modelo chave-na-mão replicável noutros lugares do mundo.","zh": "在马达加斯加启用首个试点中心，设计为可在世界其他地区复制的交钥匙模式。"},"blueprint.axe_t": {"en": "Why the China → Madagascar axis?","pt": "Porquê o eixo China → Madagáscar?","zh": "为什么是中国 → 马达加斯加？"},"blueprint.axe_d": {"en": "Direct geographical proximity across the Indian Ocean drastically cuts logistics costs. Spare parts, motors and energy equipment arrive by a short sea route, with no needless transhipment.","pt": "A proximidade geográfica direta pelo oceano Índico reduz drasticamente os custos logísticos. Peças, motores e equipamento energético chegam por uma rota marítima curta, sem transbordo inútil.","zh": "经印度洋的直线距离大幅降低物流成本。备件、电机与能源设备走一条短的海运路线，无需多余的转运。"},"blueprint.axe_d2": {"en": "This axis also makes continuous supply of parts and maintenance easier: an Isle that depends on parts from the other side of the world does not last.","pt": "Este eixo facilita também o abastecimento contínuo de peças e a manutenção: uma Ilha dependente de peças do outro lado do mundo não dura.","zh": "这条轴线也便于持续供货与维护：依赖地球另一端零件的岛屿无法长久。"},"blueprint.badge": {"en": "📐 BLUEPRINT V2 — GOVERNANCE & TRANSPARENCY","pt": "📐 BLUEPRINT V2 — GOVERNANÇA E TRANSPARÊNCIA","zh": "📐 蓝图 V2 — 治理与透明"},"blueprint.titre": {"en": "Transparency & architecture of the Realia ecosystem (V2)","pt": "Transparência e arquitetura do ecossistema Realia (V2)","zh": "Realia 生态的透明与架构（V2）"},"blueprint.sous": {"en": "How technology, solidarity real estate and digital creation fund themselves in service of our humanitarian mission.","pt": "Como tecnologia, imobiliário solidário e criação digital se autofinanciam a serviço da nossa missão humanitária.","zh": "技术、公益不动产与数字创作如何自我造血，服务于我们的人道使命。"},"blueprint.tr_titre": {"en": "Transparency commitment — seeding phase","pt": "Compromisso de transparência — fase de arranque","zh": "透明承诺——启动阶段"},"blueprint.tr_txt": {"en": "Today, the NGO and the holding are not yet registered. During this R&D seeding phase, 100 % of what comes in — Ko-fi and Tipeee donations, hardware given through the wishlist, shop commissions — goes to three items, and only those:","pt": "Hoje, a ONG e a holding ainda não estão registradas. Nesta fase de arranque de P&D, 100 % do que entra — doações Ko-fi e Tipeee, material doado pela lista, comissões da loja — vai para três itens, e só eles:","zh": "目前，非政府组织与控股公司尚未注册。在研发启动阶段，所有进账——Ko-fi 与 Tipeee 捐助、心愿单捐赠的设备、商店佣金——只用于三项："},"blueprint.tr_1": {"en": "Biomedical sensors (EEG, sEMG, isolated FES module).","pt": "Sensores biomédicos (EEG, sEMG, módulo FES isolado).","zh": "生物医学传感器（脑电、肌电、隔离式 FES 模块）。"},"blueprint.tr_2": {"en": "Development of the open-source harnesses and the digital twin.","pt": "Desenvolvimento dos arnêses abertos e do gêmeo digital.","zh": "开源背具与数字孪生的开发。"},"blueprint.tr_3": {"en": "Building the initial legal capital (NGO and holding incorporation costs).","pt": "A constituição do capital jurídico inicial (custos de criação da ONG e da holding).","zh": "构建初始法律资本（非政府组织与控股公司的注册费用）。"},"blueprint.tr_note": {"en": "No salaries, no overhead, no unlisted spending. Receipts are published as we go.","pt": "Sem salários, sem custos de estrutura, sem despesas não listadas. Os comprovantes são publicados à medida que saem.","zh": "没有薪资，没有管理费用，没有未列支出。凭证随发生随公布。"},"blueprint.archi_titre": {"en": "Two levels, one mission","pt": "Dois níveis, uma única missão","zh": "两个层级，同一个使命"},"blueprint.archi_lead": {"en": "On one side matter — a place, assets, revenue. On the other software — agents, contracts, flows. Neither is enough alone.","pt": "De um lado a matéria — um lugar, ativos, receita. Do outro o software — agentes, contratos, fluxos. Nenhum dos dois basta sozinho.","zh": "一边是物质——场所、资产、收入。另一边是软件——智能体、合约、资金流。缺一不可。"},"blueprint.r1t": {"en": "R'Station — the agnostic mother","pt": "R'Station — a mãe agnóstica","zh": "R'Station——不挑技术的母体"},"blueprint.r1d": {"en": "Physical and logical platform: hotel or riad, accessible FabLab, inclusive school, farm cooperative. It provides the frame, the tangible assets and the base revenue. First pilot (Genesis Block) in Madagascar, designed as a replicable network model.","pt": "Plataforma física e lógica: hotel ou riad, FabLab acessível, escola inclusiva, cooperativa agrícola. Fornece o quadro, os ativos tangíveis e a receita de base. Primeiro piloto (Genesis Block) em Madagascar, concebida como modelo reticular replicável.","zh": "实体与逻辑平台：酒店或庭院客栈、无障碍创客工坊、包容性学校、农业合作社。它提供框架、有形资产与基础收入。首个试点（创世区块）在马达加斯加，设计为可复制到各地的网络模型。"},"blueprint.r2t": {"en": "The DevKit — the digital CTO","pt": "O DevKit — o CTO digital","zh": "DevKit——数字技术官"},"blueprint.r2d": {"en": "Software infrastructure: AI agents, smart contracts, oracles. It runs the R'Station, secures the flows, automates content production and verifies what gets published.","pt": "Infraestrutura de software: agentes de IA, contratos inteligentes, oráculos. Opera a R'Station, protege os fluxos, automatiza a produção de conteúdo e verifica o que é publicado.","zh": "软件基础设施：人工智能智能体、智能合约、预言机。它运营 R'Station、保障资金流、自动化内容生产，并核验公开内容。"},"blueprint.jur_titre": {"en": "Separating risks to protect the mission","pt": "Separar riscos para proteger a missão","zh": "分离风险，保护使命"},"blueprint.jur_lead": {"en": "A place that heals and a place that earns money must not stand on the same legal ground. The land stays with the mission; commerce lives beside it, and pays.","pt": "Um lugar que cuida e um lugar que ganha dinheiro não devem estar no mesmo terreno jurídico. A terra fica com a missão; o comércio vive ao lado, e paga.","zh": "治疗之地与盈利之地不能站在同一块法律土地上。土地归使命；商业在旁边经营，并支付租金。"},"blueprint.ong_t": {"en": "The NGO — social and land base","pt": "A ONG — base social e fundiária","zh": "非政府组织——社会与土地基础"},"blueprint.ong_d": {"en": "Holds the land, the school, the centre for disabled children and women. It does not trade: it leases commercial space to operating subsidiaries and collects rent.","pt": "Detém a terra, a escola, o centro para crianças com deficiência e mulheres. Não comercializa: aluga espaços comerciais às subsidiárias e recebe aluguel.","zh": "持有土地、学校、残疾儿童与女性中心。它不经商：把商业空间租给运营子公司并收取租金。"},"blueprint.holding_t": {"en": "International holding & specialised arms","pt": "Holding internacional e polos especializados","zh": "国际控股与专业板块"},"blueprint.holding_d": {"en": "Control structure owned by the mission. It separates two arms: Digital / Tech (DevKit, agents, infrastructure) and Content / Media & IP (LunaGalaxie, training, protected image rights).","pt": "Estrutura de controle detida pela missão. Separa dois polos: Digital / Tech (DevKit, agentes, infraestrutura) e Content / Mídia & PI (LunaGalaxie, formações, direitos de imagem protegidos).","zh": "由使命持有的控制结构。它分离两个板块：数字／技术（DevKit、智能体、基础设施）与内容／媒体与知识产权（LunaGalaxie、培训、受保护的肖像权）。"},"blueprint.flux": {"en": "Rent + patronage","pt": "Aluguel + patrocínio","zh": "租金＋捐赠"},"blueprint.wf_titre": {"en": "The waterfall — where every earned euro goes","pt": "O waterfall — para onde vai cada euro ganho","zh": "瀑布分配——每一欧元去向"},"blueprint.wf_lead": {"en": "Each R'Station splits its revenue automatically. This key is public, written into the contract, and is not negotiated in committee.","pt": "Cada R'Station divide sua receita automaticamente. Esta chave é pública, escrita no contrato, e não se negocia em comitê.","zh": "每个 R'Station 自动分配收入。这份比例公开、写进合约，不在委员会里讨价还价。"},"blueprint.w40": {"en": "Operating treasury","pt": "Tesouraria operacional","zh": "运营资金"},"blueprint.w40d": {"en": "Local salaries, maintenance, energy, raw materials.","pt": "Salários locais, manutenção, energia, matéria-prima.","zh": "本地薪资、维护、能源、原材料。"},"blueprint.w30": {"en": "Yield & usage rights","pt": "Rendimento e direitos de uso","zh": "收益与使用权"},"blueprint.w30d": {"en": "Hotel token: open to the public and the diaspora, with real usage rights.","pt": "Token Hotel: acesso ao público e à diáspora, com direitos de uso reais.","zh": "酒店代币：面向公众与侨民，附带真实使用权。"},"blueprint.w20": {"en": "R&D & impact reinvestment","pt": "Reinvestimento em P&D e impacto","zh": "研发与影响力再投入"},"blueprint.w20d": {"en": "Ecosystem / DevKit token: exoskeletons, prototypes, innovation.","pt": "Token Ecossistema / DevKit: exoesqueletos, protótipos, inovação.","zh": "生态／DevKit 代币：外骨骼、原型、创新。"},"blueprint.w10": {"en": "Automatic patronage","pt": "Patrocínio automático","zh": "自动捐赠"},"blueprint.w10d": {"en": "Direct payment to the NGO: school and care centre are funded continuously.","pt": "Pagamento direto à ONG: escola e centro de cuidado financiados continuamente.","zh": "直接拨付非政府组织：学校与护理中心获得持续资助。"},"blueprint.tech_titre": {"en": "Tech-for-equity — the DevKit for a share of growth","pt": "Tech-for-equity — o DevKit por uma parte do crescimento","zh": "技术换股权——以 DevKit 换取成长份额"},"blueprint.tech_lead": {"en": "The DevKit is not sold by the day. It is deployed in partner SMEs in exchange for equity, a commitment, or a contribution to the ecosystem.","pt": "O DevKit não é vendido por dia. É instalado em PMEs parceiras em troca de participação, compromisso ou contribuição ao ecossistema.","zh": "DevKit 不按天出售。它以股权、承诺或对生态的贡献为对价，部署到合作中小企业。"},"blueprint.tier1": {"en": "Tier 1 — Pilot","pt": "Tier 1 — Piloto","zh": "第一层——试点"},"blueprint.tier1d": {"en": "DevKit deployment, support, first automation. No fixed term.","pt": "Instalação do DevKit, acompanhamento, primeira automação. Sem prazo fixo.","zh": "部署 DevKit、陪跑、首轮自动化。无固定期限。"},"blueprint.tier2": {"en": "Tier 2 — Player","pt": "Tier 2 — Ator","zh": "第二层——参与者"},"blueprint.tier2d": {"en": "The partner runs the DevKit on its own flows and feeds the ecosystem with use cases.","pt": "O parceiro opera o DevKit nos próprios fluxos e alimenta o ecossistema com casos de uso.","zh": "伙伴在自身业务中运营 DevKit，并以用例反哺生态。"},"blueprint.tier3": {"en": "Tier 3 — Architect","pt": "Tier 3 — Arquiteto","zh": "第三层——架构师"},"blueprint.tier3d": {"en": "A 3-year commitment with reverse vesting: the share is earned by building, not by signing.","pt": "Compromisso de 3 anos com reverse vesting: a participação se ganha construindo, não assinando.","zh": "三年承诺，附反向归属：股权靠建设赢得，而不是靠签字。"},"blueprint.road_titre": {"en": "Roadmap","pt": "Roteiro","zh": "路线图"},"blueprint.p0t": {"en": "Phase 0 — Legal foundations & IP","pt": "Fase 0 — Fundações jurídicas e PI","zh": "第 0 阶段——法律与知识产权基础"},"blueprint.p0d": {"en": "NGO and holding articles, trademark filing, image-rights assignment contracts.","pt": "Estatutos da ONG e da holding, registro de marcas, contratos de cessão de direitos de imagem.","zh": "非政府组织与控股公司章程、商标申请、肖像权转让合同。"},"blueprint.p1t": {"en": "Phase 1 — Pilot asset & hotel token","pt": "Fase 1 — Ativo-piloto e Token Hotel","zh": "第 1 阶段——试点资产与酒店代币"},"blueprint.p1d": {"en": "First site in Madagascar, waterfall live, usage token under KYC/AML.","pt": "Primeiro local em Madagascar, waterfall em produção, token de uso sob KYC/AML.","zh": "马达加斯加首处场所、瀑布分配上线、使用型代币受 KYC/AML 监管。"},"blueprint.p2t": {"en": "Phase 2 — FabLab, cooperative & ecosystem token","pt": "Fase 2 — FabLab, cooperativa e Token Ecossistema","zh": "第 2 阶段——创客工坊、合作社与生态代币"},"blueprint.p2d": {"en": "Local production, training young people, second funding layer for R&D.","pt": "Produção local, formação de jovens, segunda camada de financiamento de P&D.","zh": "本地生产、青年培训、研发的第二层资金来源。"},"blueprint.p3t": {"en": "Phase 3 — Global network & autonomous agents","pt": "Fase 3 — Rede mundial e agentes autônomos","zh": "第 3 阶段——全球网络与自主智能体"},"blueprint.p3d": {"en": "Replicating R'Stations, agent orchestration, mission funded by design.","pt": "Replicação das R'Stations, orquestração por agentes, missão financiada por construção.","zh": "复制 R'Station、由智能体编排，使命靠结构自养。"},"blueprint.legal": {"en": "Strategic architecture document V2, provided for information and subject to change; tokenised asset deployment will be strictly framed by applicable financial regulations and KYC/AML procedures.","pt": "Documento de arquitetura estratégica V2, apresentado a título informativo e evolutivo; a implantação de ativos tokenizados será estritamente enquadrada pelas regulações financeiras e procedimentos KYC/AML vigentes.","zh": "本 V2 战略架构文件仅供参考且会演进；代币化资产的部署将严格受现行金融监管与 KYC/AML 程序约束。"},"blueprint.cta": {"en": "See the social mission","pt": "Ver a missão social","zh": "查看社会使命"},"virtuel.carte": {"en": "Virtual Lab","pt": "Laboratório virtual","zh": "虚拟实验室"},"virtuel.descr": {"en": "Body before metal: simulate instead of machining blind.","pt": "O corpo antes do metal: simular em vez de usinar às cegas.","zh": "先有身体，后有金属：先仿真，而不是盲目加工。"},"neuroexo.carte": {"en": "NeuroExoAI harness","pt": "Arnês NeuroExoAI","zh": "NeuroExoAI 背具"},"neuroexo.descr": {"en": "The hard loop: sEMG, FES and safety under 20 ms.","pt": "O laço duro: sEMG, FES e segurança abaixo de 20 ms.","zh": "硬实时回路：20 毫秒内的 sEMG、FES 与安全。"},"devkit.carte": {"en": "RealiDevKit harness","pt": "Arnês RealiDevKit","zh": "RealiDevKit 背具"},"devkit.descr": {"en": "The software factory that builds everything else.","pt": "A fábrica de software que constrói todo o resto.","zh": "构建其他一切的软件工厂。"},"realia.carte": {"en": "RealiaStation","pt": "RealiaStation","zh": "RealiaStation"},"realia.descr": {"en": "The study where sub-agents are orchestrated.","pt": "O gabinete onde os subagentes são orquestrados.","zh": "指挥子智能体的工作室。"},"luna.carte": {"en": "LunaGalaxie","pt": "LunaGalaxie","zh": "LunaGalaxie"},"luna.descr": {"en": "The voice of the project, aboard the GhostSheller.","pt": "A voz do projeto, a bordo do GhostSheller.","zh": "项目的声音，乘坐 GhostSheller。"},"social.carte": {"en": "Social project — the Integrated Isle","pt": "Projeto social — a Ilha Integrada","zh": "社会项目——综合之岛"},"social.descr": {"en": "The replicable NGO model, first stone in Madagascar.","pt": "O modelo de ONG replicável, primeira pedra em Madagascar.","zh": "可复制的非政府组织模式，第一站在马达加斯加。"},"archi.carte": {"en": "The Architect","pt": "O Arquiteto","zh": "建筑师"},"archi.descr": {"en": "A rebirth, a cause, a mission.","pt": "Um renascimento, uma causa, uma missão.","zh": "一次重生，一项事业，一个使命。"},"wish.carte": {"en": "Hardware wishlist","pt": "Lista de material","zh": "设备心愿单"},"wish.descr": {"en": "Fund one precise component, not a pool.","pt": "Financiar um componente exato, não um bolo.","zh": "资助一个具体的部件，而不是一笔糊涂账。"},"boutique.carte": {"en": "Christmas shop","pt": "Loja de Natal","zh": "圣诞商店"},"boutique.descr": {"en": "Shop as usual, fund the project at no extra cost.","pt": "Comprar como sempre, financiar o projeto sem custo extra.","zh": "照常购物，零额外成本地资助项目。"},"tiroir.suivant": {"en": "Next drawer","pt": "Próxima gaveta","zh": "下一个抽屉"},"tiroir.dernier": {"en": "Last drawer","pt": "Última gaveta","zh": "最后一个抽屉"}};
